# fmt: on


def _bytes_to_lut(data: bytes) -> np.ndarray:
    """Convert raw bytes to (256, 3) uint8 numpy array."""
    return np.frombuffer(data, dtype=np.uint8).reshape(256, 3).copy()


# Lazy cache for numpy arrays
_cache: Dict[str, np.ndarray] = {}


# Map of colormap name -> raw bytes
_COLORMAP_BYTES: Dict[str, bytes] = {
    # Microscopy linear ramps
    "green": _GREEN_BYTES,
    "magenta": _MAGENTA_BYTES,
    "cyan": _CYAN_BYTES,
    "red": _RED_BYTES,
    "blue": _BLUE_BYTES,
    "yellow": _YELLOW_BYTES,
    "gray": _GRAY_BYTES,
    "orange": _ORANGE_BYTES,
    # BOP (Blue-Orange-Purple)
    "bop_blue": _BOP_BLUE_BYTES,
    "bop_orange": _BOP_ORANGE_BYTES,
    "bop_purple": _BOP_PURPLE_BYTES,
    # Perceptually uniform
    "viridis": _VIRIDIS_BYTES,
    "inferno": _INFERNO_BYTES,
    "plasma": _PLASMA_BYTES,
    "turbo": _TURBO_BYTES,
    # Domain-specific
    "fire": _FIRE_BYTES,
    "ice": _ICE_BYTES,
    "phase": _PHASE_BYTES,
    # Diverging
    "RdBu": _RDBU_BYTES,
    "coolwarm": _COOLWARM_BYTES,
}


def get_builtin_lut(name: str) -> np.ndarray:
    """Get a built-in colormap as a (256, 3) uint8 numpy array.

    Returns a copy to prevent mutation of the cached array.
    """
    if name not in _COLORMAP_BYTES:
        raise KeyError(f"Unknown built-in colormap: {name!r}")
    if name not in _cache:
        _cache[name] = _bytes_to_lut(_COLORMAP_BYTES[name])
    return _cache[name].copy()


BUILTIN_COLORMAP_NAMES: list[str] = list(_COLORMAP_BYTES.keys())
